import functools
from typing import Callable, Any, Tuple, Type

class IO:
    pass

class FileSystem:
    pass

def has_effects(*effects: Type) -> Callable:
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        wrapper.effects = effects
        return wrapper
    return decorator

def computeSum(a: int, b: int) -> int:
    return a + b

@has_effects(IO)
def printSum(a: int, b: int) -> None:
    result = computeSum(a, b)
    print(f"Sum: {result}")

@has_effects(IO, FileSystem)
def logToFile(filename: str, message: str) -> None:
    with open(filename, 'w') as f:
        f.write(message)

def main() -> None:
    sum_result = computeSum(10, 20)
    printSum(10, 20)
    logToFile("output.txt", f"Sum was {sum_result}")
    print("Done")

if __name__ == "__main__":
    main()

