from dataclasses import dataclass
from typing import Generic, TypeVar, Callable

T = TypeVar('T')
U = TypeVar('U')


@dataclass
class Ok(Generic[T]):
    value: T

    def bind(self, func: Callable[[T], 'Result[U]']) -> 'Result[U]':
        return func(self.value)

    def is_ok(self) -> bool:
        return True


@dataclass
class Err(Generic[T]):
    message: str

    def bind(self, func: Callable[[T], 'Result[U]']) -> 'Result[U]':
        return Err(self.message)

    def is_ok(self) -> bool:
        return False


Result = Ok[T] | Err[T]


def parse_int(s: str) -> Result[int]:
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")


def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)


def print_result(result: Result[int]) -> None:
    if isinstance(result, Ok):
        print(f"Result: {result.value}")
    else:
        print(f"Error: {result.message}")


# Test case 1: parse_int("10") then divide by 2
result1 = parse_int("10").bind(lambda x: divide_safe(x, 2))
print_result(result1)

# Test case 2: parse_int("10") then divide by 0
result2 = parse_int("10").bind(lambda x: divide_safe(x, 0))
print_result(result2)

# Test case 3: parse_int("abc")
result3 = parse_int("abc")
print_result(result3)

