type Tree = Leaf(int) | Node(Tree, int, Tree)

export func tree_sum(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }
}

export func find_max(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(Leaf(x), v, Leaf(y)) =>
      match v {
        m if m >= x && m >= y => m,
        m if x >= y => x,
        m => y
      },
    Node(l, v, r) => {
      let lm = find_max(l);
      let rm = find_max(r);
      match v {
        m if m >= lm && m >= rm => m,
        m if lm >= rm => lm,
        m => rm
      }
    }
  }
}

export func main() -> () ! {IO} {
  let tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let s = tree_sum(tree);
  let m = find_max(tree);
  println("Sum: " ++ show(s));
  println("Max: " ++ show(m))
}

