from typing import TypedDict

class UserProfile(TypedDict):
    age: int
    city: str

class User(TypedDict):
    name: str
    profile: UserProfile

def getCity(user: User) -> str:
    return user["profile"]["city"]

alice: User = {
    "name": "Alice",
    "profile": {"age": 30, "city": "NYC"}
}

